void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.xy;

    vec3 top_left_color = vec3(1, 1, 1);
    vec3 top_right_color = vec3(1, 0, 1);
    vec3 btm_left_color = vec3(0, 0, 1);
    vec3 btm_right_color = vec3(1, 0, 0);

    vec3 c0 = uv.x * (top_right_color - top_left_color) + top_left_color;
    vec3 c1 = uv.x * (btm_right_color - btm_left_color) + btm_left_color;

    vec3 c = uv.y * (c0 - c1) + c1;

    fragColor = vec4(c,1.0);
}
